def Strongest_Extension(class_name, extensions):
    strong = extensions[0]
    my_val = sum(1 for x in extensions[0] if x.isalpha() and x.isupper()) - sum(1 for x in extensions[0] if x.isalpha() and x.islower())
    for s in extensions:
        val = sum(1 for x in s if x.isalpha() and x.isupper()) - sum(1 for x in s if x.isalpha() and x.islower())
